CREATE TABLE t1(a, b); CREATE INDEX i1 ON t1(a, b) WHERE a<7; CREATE INDEX i2 ON t1(b, a) WHERE a<7; INSERT INTO t1 VALUES(1,2); INSERT INTO t1 VALUES(5,6); INSERT INTO t1 VALUES(7,8); INSERT INTO t1 VALUES(9,10); PRAGMA writable_schema=1; UPDATE sqlite_master SET sql='CREATE INDEX i1 ON t1(a, b)' WHERE name='i1'; UPDATE sqlite_master SET sql='CREATE INDEX i2 ON t1(b, a)' WHERE name='i2';